  "content": ".threshold-list li\\\").length,\\n+      hasEquityPath: Boolean(equityLine && (equityLine.getAttribute(\\\"d\\\") || \\\"\\\").length > 100),\\n+      scrollWidth: document.documentElement.scrollWidth,\\n+      bodyScrollWidth: document.body.scrollWidth,\\n+      clientWidth,\\n+      innerWidth: window.innerWidth,\\n+      overflowing,\\n+      title: document.title,\\n+      h1: document.querySelector(\\\".brand-copy h1\\\")?.textContent?.replace(/\\\\s+/g, \\\" \\\").trim() ?? \\\"\\\",\\n+    };\\n+  }, viewport.columns);\\n+}\\n+\\n+async function validateMetrics(metrics, viewport, errors, responseStatus) {\\n+  if (responseStatus && responseStatus >= 400) fail(`HTTP ${responseStatus} at ${viewport.width}px`);\\n+  if (errors.length) fail(`Browser errors at ${viewport.width}px: ${errors.join(\\\" | \\\")}`);\\n+  if (metrics.cards !== 8) fail(`Expected 8 agent cards at ${viewport.width}px, found ${metrics.cards}`);\\n+  if (JSON.stringify(metrics.agents) !== JSON.stringify(EXPECTED_AGENTS)) {\\n+    fail(`Unexpected agent ids at ${viewport.width}px: ${metrics.agents.join(\\\", \\\")}`);\\n+  }\\n+  if (metrics.columns !== viewport.columns) {\\n+    fail(`Expected ${viewport.columns} agent columns at ${viewport.width}px, found ${metrics.columns}`);\\n+  }\\n+  if (metrics.roomWidth < 300 || metrics.roomHeight < 180) {\\n+    fail(`Pixel room is too small at ${viewport.width}px (${metrics.roomWidth}x${metrics.roomHeight})`);\\n+  }\\n+  if (metrics.candleBodies < 20) fail(`Candle chart did not render at ${viewport.width}px`);\\n+  if (metrics.stations < 6) fail(`Pixel room stations missing at ${viewport.width}px`);\\n+  if (metrics.thresholds !== 8) fail(`Threshold table incomplete at ${viewport.width}px`);\\n+  if (!metrics.hasEquityPath) fail(`Equity chart path missing at ${viewport.width}px`);\\n+  if (metrics.scrollWidth > metrics.clientWidth + 1 || metrics.bodyScrollWidth > metrics.clientWidth + 1) {\\n+    fail(`Horizontal overflow at ${viewport.width}px: scrollWidth=${metrics.scrollWidth}, clientWidth=${metrics.clientWidth}`);\\n+  }\\n+  if (metrics.overflowing.length) {\\n+    fail(`Elements overflow at ${viewport.width}px: ${metrics.overflowing.join(\\\", \\\")}`);\\n+  }\\n+  if (!metrics.title.includes(\\\"GROKBOT\\\") || !metrics.h1.includes(\\\"GROKBOT\\\")) {\\n+    fail(`Unexpected page title/brand at ${viewport.width}px`);\\n+  }\\n+}\\n+\\n+async function runInteractions(browser) {\\n+  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });\\n+  const errors = [];\\n+  page.on(\\\"pageerror\\\", (error) => errors.push(error.message));\\n+  page.on(\\\"console\\\", (message) => {\\n+    if (message.type() === \\\"error\\\" && !message.location().url?.endsWith(\\\"/favicon.ico\\\")) { errors.push(message.text()); }\\n+  });\\n+\\n+  await page.goto(BASE_URL, { waitUntil: \\\"domcontentloaded\\\" });\\n+  await waitForReady(page);\\n+\\n+  await page.locator('[data-testid=\\\"pixel-room\\\"]').screenshot({\\n+    path: path.join(SHOTS, \\\"pixel-room-1440.png\\\"),\\n+  });\\n+\\n+  const chart = page.locator('[data-testid=\\\"equity-chart\\\"]');\\n+  await chart.scrollIntoViewIfNeeded();\\n+  const chartBox = await chart.boundingBox();\\n+  if (!chartBox) fail(\\\"Equity chart has no layout box\\\");\\n+  await page.mouse.move(chartBox.x + chartBox.width * 0.62, chartBox.y + chartBox.height * 0.42);\\n+  await page.waitForSelector(\\\".chart-tooltip\\\", { timeout: 3000 });\\n+  const tooltip = (await page.locator(\\\".chart-tooltip\\\").innerText()).replace(/\\\\s+/g, \\\" \\\").trim();\\n+  await page.locator(\\\".equity-panel\\\").screenshot({\\n+    path: path.join(SHOTS, \\\"equity-hover-1440.png\\\"),\\n+  });\\n+\\n+  const readTick = async () => {\\n+    const text = await page.locator(\\\".section-meta\\\").innerText();\\n+    const match = text.match(/TICK\\\\s+(\\\\d+)/);\\n+    return match ? Number(match[1]) : -1;\\n+  };\\n+\\n+  const beforeHold = await readTick();\\n+  await page.getByRole(\\\"button\\\", { name: \\\"Pause simulation\\\" }).click();\\n+  await page.waitForSelector(\\\".room-held-badge\\\", { timeout: 3000 });\\n+  const heldTick = await readTick();\\n+  await page.waitForTimeout(2100);\\n+  const heldTickAfterWait = await readTick();\\n+  if (heldTickAfterWait !== heldTick) fail(\\\"Stream advanced while paused\\\");\\n+\\n+  await page.getByRole(\\\"button\\\", { name: \\\"Advance simulation one tick\\\" }).click();\\n+  await page.waitForTimeout(200);\\n+  const steppedTick = await readTick();\\n+  if (steppedTick <= heldTick) fail(\\\"STEP did not advance exactly one simulation tick\\\");\\n+\\n+  await page.getByRole(\\\"button\\\", { name: \\\"Resume simulation\\\" }).click();\\n+  await page.waitForTimeout(2100);\\n+  const resumedTick = await readTick();\\n+  if (resumedTick <= steppedTick) fail(\\\"Stream did not resume after RESUME\\\");\\n+\\n+  if (errors.length) fail(`Browser errors during interaction: ${errors.join(\\\" | \\\")}`);\\n+\\n+  await page.close();\\n+  return {\\n+    beforeHold,\\n+    heldTick,\\n+    heldTickAfterWait,\\n+    steppedTick,\\n+    resumedTick,\\n+    tooltip,\\n+    roomScreenshot: \\\"screenshots/pixel-room-1440.png\\\",\\r\\n+    mode: SAVE ? \\\"save\\\" : \\\"verify\\\",\\n+    hoverScreenshot: \\\"screenshots/equity-hover-1440.png\\\",\\n+  };\\n+}\\n+\\n+let server;\\n+let browser;\\n+try {\\n+  server = await createServer({\\n+    root: ROOT,\\n+    logLevel: \\\"error\\\",\\n+    server: { port: PORT, strictPort: true },\\n+  });\\n+  await server.listen();\\n+\\n+  browser = await chromium.launch({ executablePath, headless: true });\\n+  console.log(`Chrome: ${executablePath}`);\\r\\n+  console.log(`Mode: ${SAVE ? \\\"save deliverable screenshots\\\" : \\\"verify only (temp screenshots)\\\"}`);\\n+  console.log(`Preview: ${BASE_URL}`);\\n+\\n+  for (const viewport of VIEWPORTS) {\\n+    const page = await browser.newPage({\\n+      viewport: { width: viewport.width, height: viewport.height },\\n+      deviceScaleFactor: 1,\\n+    });\\n+    const errors = [];\\n+    page.on(\\\"pageerror\\\", (error) => errors.push(error.message));\\n+    page.on(\\\"console\\\", (message) => {\\n+      if (message.type() === \\\"error\\\" && !message.location().url?.endsWith(\\\"/favicon.ico\\\")) {\\n+        errors.push(message.text());\\n+      }\\n+    });\\n+\\n+    const response = await page.goto(BASE_URL, { waitUntil: \\\"domcontentloaded\\\" });\\n+    await waitForReady(page);\\n+    const metrics = await inspectViewport(page, viewport);\\n+    await validateMetrics(metrics, viewport, errors, response ? response.status() : 0);\\n+\\n+    const shotPath = path.join(SHOTS, `${viewport.name}.png`);\\n+    await page.screenshot({ path: shotPath, fullPage: true });\\n+    const size = fs.statSync(shotPath).size;\\n+    if (size < 30_000) fail(`Screenshot suspiciously small at ${viewport.width}px (${size} bytes)`);\\n+\\n+    const result = {\\n+      viewport: `${viewport.width}x${viewport.height}`,\\n+      columns: metrics.columns,\\n+      room: `${metrics.roomWidth}x${metrics.roomHeight}`,\\n+      cards: metrics.cards,\\n+      candleBodies: metrics.candleBodies,\\n+      scrollWidth: metrics.scrollWidth,\\n+      clientWidth: metrics.clientWidth,\\n+      screenshot: `screenshots/${viewport.name}.png`,\\n+      screenshotBytes: size,\\n+    };\\n+    report.viewports.push(result);\\n+    console.log(`PASS ${result.viewport}: ${result.columns} cols, room ${result.room}, no overflow, ${Math.round(size / 1024)} KB`);\\n+\\n+    await page.close();\\n+  }\\n+\\n+  report.interactions = await runInteractions(browser);\\n+  console.log(\\n+    `PASS pause/resume: held tick ${report.interactions.heldTick}, stepped ${report.interactions.steppedTick}, resumed ${report.interactions.resumedTick}`,\\n+  );\\n+  console.log(`PASS chart hover: ${report.interactions.tooltip}`);\\n+\\n+  fs.writeFileSync(path.join(SHOTS, \\\"verification.json\\\"), JSON.stringify(report, null, 2));\\n+  console.log(\\\"Screenshots written to screenshots/\\\");\\n+} catch (error) {\\n+  report.error = error instanceof Error ? error.message : String(error);\\n+  fs.writeFileSync(path.join(SHOTS, \\\"verification.json\\\"), JSON.stringify(report, null, 2));\\n+  console.error(`SCREENSHOT VERIFICATION FAILED: ${report.error}`);\\n+  process.exitCode = 1;\\n+} finally {\\n+  if (browser) await browser.close().catch(() => {});\\n+  if (server) await server.close().catch(() => {});\\n+}\\n+\",\"complete\":true},{\"path\":\"src/App.test.tsx\",\"status\":\"added\",\"after\":{\"hash\":\"366cb11115511baa02e72b46f546c24257b25bc7fdb691220d0b4eb363bf9be7\",\"size\":5139,\"binary\":false},\"diff\":\"--- /dev/null\\n+++ src/App.test.tsx\\n-\\n+import { act, fireEvent, render, screen, within } from \\\"@testing-library/react\\\";\\n+import { beforeEach, describe, expect, it, vi } from \\\"vitest\\\";\\n+import App from \\\"./App\\\";\\n+import { AgentStreamProvider } from \\\"./data/AgentStream\\\";\\n+\\n+function renderDashboard(seed = 7) {\\n+  return render(\\n+    <AgentStreamProvider seed={seed} tickMs={1000}>\\n+      <App />\\n+    </AgentStreamProvider>,\\n+  );\\n+}\\n+\\n+function tickLabel(): string {\\n+  return screen.getByText(/TICK \\\\d{4}/).textContent ?? \\\"\\\";\\n+}\\n+\\n+describe(\\\"trading desk dashboard\\\", () => {\\n+  beforeEach(() => {\\n+    vi.useFakeTimers();\\n+  });\\n+\\n+  it(\\\"renders exactly eight distinct agent cards, the pixel room and both financial charts\\\", () => {\\n+    renderDashboard();\\n+\\n+    const cards = screen.getAllByTestId(\\\"agent-card\\\");\\n+    expect(cards).toHaveLength(8);\\n+\\n+    const names = cards.map((card) => within(card).getByRole(\\\"heading\\\", { level: 3 }).textContent);\\n+    expect(names).toEqual([\\\"CHIEF\\\", \\\"SCAN\\\", \\\"VET\\\", \\\"SOCIAL\\\", \\\"SIZE\\\", \\\"FILLS\\\", \\\"RISK\\\", \\\"CRAWLER\\\"]);\\n+    expect(new S